.forge-hero img { max-width: 100%; display: block; }

.forge-hero .container { max-width: var(--max-width); margin-inline: auto; padding-inline: clamp(20px, 5vw, 64px); }

.forge-hero .eyebrow {
    font-family: var(--body-font-family);
    font-weight: 700; font-size: 13px; letter-spacing: 0.01em;
    color: var(--color-gray-700); margin: 0 0 var(--spacing-md);
  }

.forge-hero .btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px;
    height: 44px; padding-inline: 24px; border-radius: var(--pill);
    font-family: var(--body-font-family); font-size: 15px; font-weight: 700;
    text-decoration: none; border: 1.5px solid transparent; cursor: pointer;
    transition: background 200ms var(--ease), color 200ms var(--ease); white-space: nowrap; }

.forge-hero .btn--primary { background: var(--color-accent); color: var(--s2a-color-gray-25, #fff); }

.forge-hero .btn--primary:hover { background: var(--color-blue-deep); }

.forge-hero .container { display: grid; grid-template-columns: 1.1fr 0.9fr; gap: clamp(32px, 5vw, 72px); align-items: center; }

.forge-hero .hero__id { font-size: clamp(48px, 6.25vw, 80px); }

.forge-hero .featured { margin-top: var(--spacing-xl); padding-top: var(--spacing-lg); border-top: 1px solid rgba(0,0,0,0.1); }

.forge-hero .featured__eyebrow { color: var(--color-accent); }

.forge-hero .featured__title { font-size: var(--heading-lg); margin-bottom: var(--spacing-md); }

.forge-hero .featured .btn { margin-top: var(--spacing-lg); }

.forge-hero .hero__media { background: var(--color-warm-stone); border-radius: var(--radius); padding: var(--spacing-lg); }

.forge-hero .hero__media img { width: 100%; height: auto; border-radius: var(--radius-sm); aspect-ratio: 16 / 11; object-fit: cover; }

.forge-hero .act-dark .eyebrow { color: rgba(255,255,255,0.72); }

.forge-hero .summit .container { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(32px, 5vw, 72px); align-items: center; }

.forge-hero .contact .container { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(40px, 6vw, 96px); }

.forge-hero .site-footer .container { display: flex; align-items: center; justify-content: space-between; gap: var(--spacing-lg); flex-wrap: wrap; }

@media (max-width: 900px) {
.forge-hero .container, .forge-hero .summit .container, .forge-hero .contact .container { grid-template-columns: 1fr; }
.forge-hero .hero__media { order: -1; }
}

newBlockTasks.pageGlobalsCss:
:root {
    --heading-font-family: 'adobe-clean-display', 'Adobe Clean Display', 'Adobe Clean', 'Helvetica Neue', Arial, sans-serif;
    --body-font-family:    'adobe-clean', 'Adobe Clean', 'Helvetica Neue', Arial, sans-serif;

    --heading-xxl: clamp(48px, 6.25vw, 80px);   /* display */
    --heading-xl:  clamp(34px, 3.6vw, 56px);    /* headline */
    --heading-lg:  34px;
    --heading-md:  24px;                         /* title */
    --body:        18px;
    --body-sm:     15px;

    --line-height-heading: 0.95;
    --line-height-body:    1.5;

    /* C2 palette — inherited from _brand-extraction.json */
    --color-bg:         #ffffff;   /* Paper */
    --color-fg:         #000000;   /* Ink */
    --color-accent:     #3b63fb;   /* Adobe Blue — the only saturated colour */
    --color-blue-deep:  #274dea;   /* Adobe Blue hover */
    --color-warm-stone: #eceae7;   /* card / asset ground */
    --color-cloud:      #f8f8f8;   /* subtle ground / hairline */
    --color-gray-700:   #505050;   /* eyebrow / subtle text on light */
    --color-adobe-red:  #eb1000;   /* reserved to the wordmark only */

    --spacing-xs:  4px;
    --spacing-sm:  8px;
    --spacing-md:  16px;
    --spacing-lg:  24px;
    --spacing-xl:  48px;
    --spacing-2xl: 96px;

    --section-padding: 96px;
    --max-width:       1280px;
    --radius:          16px;
    --radius-sm:       12px;
    --pill:            999px;

    --nav-lift: 0 2px 12px rgba(0,0,0,0.08);
    --ease:     cubic-bezier(0.42, 0, 0, 1);
  }

*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; text-wrap: pretty; hanging-punctuation: first; }

body {
    margin: 0;
    font-family: var(--body-font-family);
    font-size: var(--body);
    line-height: var(--line-height-body);
    color: var(--color-fg);
    background: var(--color-bg);
    -webkit-font-smoothing: antialiased;
  }

